SET client_encoding = 'UTF8';
-- =====================================================================
-- Marketplace Freelance - sample data  (run AFTER schema.sql)
-- Usage: psql -U postgres -d lab_freelance -v ON_ERROR_STOP=1 -f database/seed.sql
--
-- Notes
--  * IDs are generated by the database, so rows are linked through natural keys
--    (email, project title, ...) instead of hard-coded numbers.
--  * password_hash values are real PBKDF2-SHA256 hashes (same format the web app uses).
--    Login passwords: admin = Sample#Pass0, Ali = Sample#Pass1, Sara = Sample#Pass2,
--    Reza = Sample#Pass3, Maryam = Sample#Pass4.
--  * Amounts are in Toman (single-currency platform, see README).
--  * The accepted proposal at the end is created with a plain UPDATE: the trigger
--    moves the project to in_progress and rejects the other pending proposals.
-- =====================================================================

BEGIN;

-- 1. Users: 1 admin + 4 regular users ----------------------------------
INSERT INTO users (first_name, last_name, email, phone, password_hash, status) VALUES
 ('مدیر',  'سیستم',   'admin@marketplace.test',     NULL,          'pbkdf2:sha256:600000$I0sAu185gRX7oDZl$d930d9ca84f0672623fe0f689d79b0b6312f25a6c4e75891c11b936977b700a0', 'active'),
 ('علی',   'احمدی',   'ali.ahmadi@example.com',     '09121111111', 'pbkdf2:sha256:600000$VP478sgWotN3Klb3$e69f7c04984228cb3dd0814c6ad86699e1b173b8b41584ac5bbb0e02f97d3b8b', 'active'),
 ('سارا',  'کریمی',   'sara.karimi@example.com',    '09122222222', 'pbkdf2:sha256:600000$sniyO0fOAfEEYmnT$32df9618054ea96194bbb89f52d7d22f2895b5be19e16c8d8ce1480d1c6f201e', 'active'),
 ('رضا',   'محمدی',   'reza.mohammadi@example.com', '09123333333', 'pbkdf2:sha256:600000$Le8pXIWBpMAedPVR$2367ac7173f96226d6e071d603306d859dc4a81fa4b42016dcd894c876abea9b', 'active'),
 ('مریم',  'حسینی',   'maryam.hosseini@example.com', NULL,         'pbkdf2:sha256:600000$H3pGVtJN30Pj5SuA$10d768da156613aced30864f5eb214528d93a026dcf618e71b116b4162523a2d', 'active');

-- 2. Admin access (first admin has granted_by = NULL) -------------------
INSERT INTO admins (user_id, granted_by)
SELECT id, NULL FROM users WHERE email = 'admin@marketplace.test';

-- 3. Categories and skills ----------------------------------------------
INSERT INTO categories (title, description) VALUES
 ('طراحی و توسعه وب',  'طراحی سایت، فروشگاه اینترنتی و برنامه‌های تحت وب'),
 ('توسعه اپلیکیشن',   'اپلیکیشن‌های موبایل اندروید و iOS'),
 ('تحلیل داده',       'تحلیل داده، گزارش‌گیری و داشبوردهای مدیریتی'),
 ('هوش مصنوعی',       'یادگیری ماشین و پردازش زبان طبیعی');

INSERT INTO skills (name) VALUES
 ('Python'), ('React'), ('SQL'), ('UX/UI'), ('Flutter'), ('Data Analysis');

-- 4. Profiles (admin has none) ------------------------------------------
INSERT INTO profiles_user (user_id, headline, bio, country, city)
SELECT u.id, v.headline, v.bio, v.country, v.city
FROM (VALUES
 ('ali.ahmadi@example.com',      'توسعه‌دهنده فول‌استک',   'هشت سال سابقه توسعه وب و موبایل.',        'ایران', 'تهران'),
 ('sara.karimi@example.com',     'مدیر محصول',             'کارفرمای فعال در حوزه فروشگاه‌های آنلاین.', 'ایران', 'اصفهان'),
 ('reza.mohammadi@example.com',  'تحلیلگر داده',           'تحلیل داده و ساخت داشبورد با Python و SQL.', 'ایران', 'شیراز'),
 ('maryam.hosseini@example.com', 'طراح UX/UI و فرانت‌اند', NULL,                                        NULL,   NULL)
) AS v(email, headline, bio, country, city)
JOIN users u ON u.email = v.email;

INSERT INTO profile_skills (profile_id, skill_id)
SELECT pr.id, s.id
FROM (VALUES
 ('ali.ahmadi@example.com',      'React'),
 ('ali.ahmadi@example.com',      'Python'),
 ('ali.ahmadi@example.com',      'SQL'),
 ('ali.ahmadi@example.com',      'Flutter'),
 ('sara.karimi@example.com',     'UX/UI'),
 ('reza.mohammadi@example.com',  'Python'),
 ('reza.mohammadi@example.com',  'SQL'),
 ('reza.mohammadi@example.com',  'Data Analysis'),
 ('maryam.hosseini@example.com', 'UX/UI'),
 ('maryam.hosseini@example.com', 'React')
) AS v(email, skill)
JOIN users u ON u.email = v.email
JOIN profiles_user pr ON pr.user_id = u.id
JOIN skills s ON s.name = v.skill;

INSERT INTO portfolio_items (profile_id, title, description, project_url, completed_on)
SELECT pr.id, v.title, v.descr, v.url, v.done::date
FROM (VALUES
 ('ali.ahmadi@example.com',      'فروشگاه آنلاین لوازم ورزشی', 'طراحی و پیاده‌سازی کامل با React', 'https://example.com/shop-demo', '2025-06-01'),
 ('reza.mohammadi@example.com',  'داشبورد فروش شرکت پخش',      'داشبورد مدیریتی با SQL و Python', NULL,                          '2025-09-15'),
 ('maryam.hosseini@example.com', 'طراحی اپ رزرو هتل',          'طراحی رابط کاربری در Figma',      'https://example.com/hotel-ux', '2025-03-20')
) AS v(email, title, descr, url, done)
JOIN users u ON u.email = v.email
JOIN profiles_user pr ON pr.user_id = u.id;

INSERT INTO certificates (profile_id, title, issuer, issued_on, expires_on, credential_url)
SELECT pr.id, v.title, v.issuer, v.issued::date, v.expires::date, v.url
FROM (VALUES
 ('ali.ahmadi@example.com',     'Meta Front-End Developer', 'Coursera', '2024-05-10', NULL,         'https://example.com/cert/ali'),
 ('reza.mohammadi@example.com', 'Google Data Analytics',    'Coursera', '2024-11-02', '2027-11-02', NULL)
) AS v(email, title, issuer, issued, expires, url)
JOIN users u ON u.email = v.email
JOIN profiles_user pr ON pr.user_id = u.id;

-- 5. Projects ------------------------------------------------------------
--   P1 Sara  : fixed  45,000,000  open
--   P2 Ali   : hourly    500,000  open      (Ali is employer here ...)
--   P3 Sara  : fixed  25,000,000  open -> becomes in_progress after acceptance below
INSERT INTO projects (employer_id, title, description, pricing_type, budget, status, deadline)
SELECT u.id, v.title, v.descr, v.ptype, v.budget, v.status,
       CASE WHEN v.days IS NULL THEN NULL ELSE now() + v.days * interval '1 day' END
FROM (VALUES
 ('sara.karimi@example.com', 'طراحی سایت فروشگاه اینترنتی',
  'طراحی و پیاده‌سازی فروشگاه اینترنتی با درگاه پرداخت و پنل مدیریت.',
  'fixed',  45000000, 'open', 60),
 ('ali.ahmadi@example.com',  'ساخت اپلیکیشن رزرو نوبت',
  'اپلیکیشن موبایل رزرو نوبت برای کلینیک‌ها (اندروید و iOS).',
  'hourly',   500000, 'open', NULL::integer),
 ('sara.karimi@example.com', 'داشبورد تحلیل داده فروش ماهانه',
  'ساخت داشبورد گزارش‌های فروش ماهانه از روی پایگاه داده موجود.',
  'fixed',  25000000, 'open', 30)
) AS v(email, title, descr, ptype, budget, status, days)
JOIN users u ON u.email = v.email;

INSERT INTO project_categories (project_id, category_id)
SELECT p.id, c.id
FROM (VALUES
 ('%فروشگاه%',  'طراحی و توسعه وب'),
 ('%رزرو نوبت%', 'توسعه اپلیکیشن'),
 ('%رزرو نوبت%', 'طراحی و توسعه وب'),
 ('%داشبورد%',  'تحلیل داده')
) AS v(pattern, category)
JOIN projects p   ON p.title LIKE v.pattern
JOIN categories c ON c.title = v.category;

INSERT INTO project_skills (project_id, skill_id)
SELECT p.id, s.id
FROM (VALUES
 ('%فروشگاه%',  'React'),
 ('%فروشگاه%',  'SQL'),
 ('%فروشگاه%',  'UX/UI'),
 ('%رزرو نوبت%', 'Flutter'),
 ('%رزرو نوبت%', 'UX/UI'),
 ('%داشبورد%',  'SQL'),
 ('%داشبورد%',  'Python'),
 ('%داشبورد%',  'Data Analysis')
) AS v(pattern, skill)
JOIN projects p ON p.title LIKE v.pattern
JOIN skills s   ON s.name = v.skill;

-- 6. Proposals (all start as pending) ------------------------------------
INSERT INTO proposals (project_id, freelancer_id, amount, cover_letter, estimated_days, estimated_hours)
SELECT p.id, u.id, v.amount, v.letter, v.days, v.hours
FROM (VALUES
 ('%فروشگاه%',   'ali.ahmadi@example.com',      40000000, 'سابقه ساخت چند فروشگاه مشابه دارم و می‌توانم در ۳۰ روز تحویل دهم.', 30,           NULL::integer),
 ('%فروشگاه%',   'reza.mohammadi@example.com',  42000000, 'آماده همکاری هستم؛ نمونه‌کار در پروفایل موجود است.',                 25,           NULL),
 ('%رزرو نوبت%', 'maryam.hosseini@example.com',   450000, 'طراحی رابط کاربری و پیاده‌سازی با Flutter را انجام می‌دهم.',           NULL::integer, 120),
 ('%داشبورد%',   'reza.mohammadi@example.com',  24000000, 'تحلیلگر داده هستم و پروژه مشابه با SQL و Python انجام داده‌ام.',      20,           NULL),
 ('%داشبورد%',   'maryam.hosseini@example.com', 23000000, 'می‌توانم داشبورد را با React و نمودارهای تعاملی بسازم.',             28,           NULL)
) AS v(pattern, email, amount, letter, days, hours)
JOIN projects p ON p.title LIKE v.pattern
JOIN users u    ON u.email = v.email;

-- 7. Accept Reza's proposal for the dashboard project.
--    Triggers: project -> in_progress, Maryam's pending proposal -> rejected.
UPDATE proposals
   SET status = 'accepted'
 WHERE id = (SELECT pr.id
               FROM proposals pr
               JOIN projects p ON p.id = pr.project_id
               JOIN users u    ON u.id = pr.freelancer_id
              WHERE p.title LIKE '%داشبورد%' AND u.email = 'reza.mohammadi@example.com');

COMMIT;

-- Quick sanity check (expected: users 5, admins 1, categories 4, skills 6, projects 3, proposals 5)
SELECT (SELECT count(*) FROM users)      AS users,
       (SELECT count(*) FROM admins)     AS admins,
       (SELECT count(*) FROM categories) AS categories,
       (SELECT count(*) FROM skills)     AS skills,
       (SELECT count(*) FROM projects)   AS projects,
       (SELECT count(*) FROM proposals)  AS proposals;
